// Shared data types for sessions, participants and the host's persisted record.
// Everything here is plain JSON-serializable data.

export const SESSION_SCHEMA_VERSION = 1;

export type TimeBudget = 30 | 50 | 80;

export type SessionStatus = 'lobby' | 'running' | 'ended';

export interface Participant {
  /** Stable participant ID, generated by the host. */
  id: string;
  /** As entered. */
  name: string;
  /** Name with a suffix when somebody else uses the same name, e.g. "Sam (2)". */
  displayName: string;
  role: string;
  isFacilitator: boolean;
  presence: 'online' | 'offline';
  status: 'active' | 'removed';
  joinedAt: number;
}

/** Placeholder structure until Epic 2 provides the real format (it is a subset of that format). */
export interface FormatRef {
  id: string;
  name: string;
  columns: { id: string; name: string; prompt?: string }[];
  checkInQuestion: string;
}

export interface SessionState {
  schemaVersion: number;
  /** Host revision: increases with every accepted change. */
  rev: number;
  sessionId: string;
  joinCode: string;
  title?: string;
  createdAt: number;
  status: SessionStatus;
  format: FormatRef;
  timeBudgetMin: TimeBudget;
  participants: Record<string, Participant>;
  /** Slices owned by later epics (phase, entries, notes, ...). */
  extensions: Record<string, unknown>;
}

/** What the Facilitator's device persists (retro.host.<sessionId>) and the reducer works on. */
export interface HostData {
  state: SessionState;
  /** token -> participantId */
  tokens: Record<string, string>;
  removedTokens: string[];
  /** participantId -> operation IDs already applied (idempotent re-sends). */
  appliedOps: Record<string, string[]>;
}

export interface ReduceContext {
  now: number;
  newId?: () => string;
  newToken?: () => string;
}

export type Effect =
  { type: 'disconnect'; participantId: string } | { type: 'participantRemoved'; participantId: string };

export type ReduceResult =
  | { ok: true; data: HostData; effects: Effect[]; participantId?: string; token?: string }
  | { ok: false; reason: string; data: HostData };
